function pick(role){const isDefense=role==='defender',available=isDefense?entries.filter(e=>e.army!==attacker.army):entries.filter(e=>e.army===selectedArmy);root.innerHTML=`<section class="intro"><span class="kicker">ÉTAPE ${stage} SUR 4</span><h1>${isDefense?'Quelle unité est attaquée ?':'Quelle unité jouez-vous ?'}</h1><p>${isDefense?'Seules les unités de l’armée adverse sont proposées.':'Choisissez d’abord la liste, puis touchez la troupe jouée.'}</p>${!isDefense?armySelector():''}${usingDemo?'<p class="notice">Mode démonstration : importez deux listes depuis la page principale pour retrouver vos propres unités ici.</p>':''}</section>${[...new Set(available.map(e=>e.label))].map(label=>`<section><div class="army-title"><b>${label}</b></div><div class="unit-grid">${available.filter(e=>e.label===label).map(tile).join('')}</div></section>`).join('')}`;root.querySelectorAll('.army-switch button').forEach(b=>b.onclick=()=>{selectedArmy=b.dataset.army;pick('attacker')});root.querySelectorAll('.unit-tile').forEach(b=>b.onclick=()=>{const e=entries.find(x=>x.id===b.dataset.id);if(isDefense){defender=e;stage=4;overview(defender,'defense')}else{attacker=e;defender=null;stage=2;overview(attacker,'attack')}});progress()}
function displayImpacts(item){return item.def.displaySections?.length?item.def.displaySections:[item.def.impact]}
function group(items,impact,title){const found=items.filter(x=>displayImpacts(x).includes(impact));return `<section><h2>${title}</h2>${found.length?found.map(x=>`<article class="tag"><strong>${x.def.name}${x.tag.value!=null?' '+x.tag.value:''}</strong><small>${definitionText(x)}</small></article>`).join(''):'<p class="notice">Aucun mot-clé renseigné pour cette rubrique. La carte reste visible pour contrôle.</p>'}</section>`}
function surgeResult(type,value){const source=type==='attack'?diceIcon('attackSurge','large'):diceIcon('defenseSurge','large');const result=value==='hit'?diceIcon('hit','large'):value==='crit'?diceIcon('crit','large'):value==='block'?diceIcon('block','large'):'<i class="no-surge" title="Aucune conversion">—</i>';return `<strong class="surge-line">${source}<b>→</b>${result}</strong>`}
function surgePanel(entry){const profile=combatProfiles[norm(entry.unit.name)];if(!profile)return `<div class="surge-panel unknown"><span>CONVERSIONS D’ADRÉNALINE</span><strong>À vérifier sur la carte</strong><small>Aucune valeur n’est inventée tant que le visuel n’a pas été contrôlé.</small></div>`;if(profile.applicable===false)return `<div class="surge-panel unknown"><span>CONVERSIONS D’ADRÉNALINE</span><strong>Profil de l’unité principale</strong><small>${profile.source} · aucune fenêtre de conversion propre n’est imprimée.</small></div>`;return `<div class="surge-panel"><span>CONVERSIONS D’ADRÉNALINE</span>${surgeResult('attack',profile.attackSurge)}${surgeResult('defense',profile.defenseSurge)}<small>Vérifié visuellement · ${profile.source}</small></div>`}
function unitVisual(entry,side=''){const fr=name(entry),img=imageFor(entry.unit.name);return `<button class="unit-card-zoom ${side}" data-card-name="${fr.replace(/"/g,'&quot;')}" data-card-image="${img}" aria-label="Voir la carte ${fr}"><img src="${img}" alt="Carte ${fr}" onerror="this.hidden=true"><span aria-hidden="true">+</span></button>`}
function overview(entry,role){const items=resolved(entry),fr=displayName(entry.unit.name);root.innerHTML=`${role==='defense'?`<div class="duel"><strong>${name(attacker)}</strong><span>ATTAQUE</span><strong>${name(defender)}</strong></div>`:''}<section class="overview ${role}"><div class="hero"><div><span>${role==='attack'?'UNITÉ JOUÉE':'UNITÉ CIBLÉE'}</span><h1>${fr}</h1><p>${entry.label}</p><p>${(entry.unit.upgrades||[]).map(u=>displayName(u.name)).join(' · ')||'Sans amélioration'}</p>${surgePanel(entry)}</div>${unitVisual(entry,role)}</div>${upgradeGallery(entry)}<div class="columns">${group(items,'autre','Déplacement & activation')}${group(items,'attaque','Attaque')}${group(items,'défense','Défense')}</div></section><div class="actions"><button class="secondary" id="back">${role==='attack'?'Changer d’unité':'Changer de cible'}</button><button class="primary" id="next">${role==='attack'?'Choisir la cible →':'Résoudre l’attaque →'}</button></div>`;bindCardViewer();$('#back').onclick=()=>{stage=role==='attack'?1:3;pick(role==='attack'?'attacker':'defender')};$('#next').onclick=()=>{if(role==='attack'){stage=3;pick('defender')}else initAttack()};progress()}
let attackStep=0,attackState=null;
const attackSteps=['Armes & portée','Jet & relances','Couvert & esquive','Modifications','Défense & bilan'];
function profileFor(card){return weaponProfiles[norm(card)]}
function initAttack(){attackStep=0;attackState={range:null,selected:{},counts:{},moved:false,engaged:false,ramEligible:false,visibleTargetModels:1,attackerWounds:0,fixedArcConfirmed:false,smallOnlyVisible:false,priorityMissionAttack:false,priorityMissionDefense:false,targetForceUpgrade:false,longShotAim:false,ionEligible:false,deathFromAbove:false,targetVehicle:false,targetNonDroidTrooper:false,targetSmallTrooper:false,activeShields:0,shieldHit:0,shieldCrit:0,guardianId:'',guardianEligible:false,guardianHits:0,guardianDefense:{block:0,surge:0,blank:0},aims:0,lethalAims:0,rerolled:0,roll:{hit:0,crit:0,surge:0,blank:0},cover:'none',coverBlock:0,coverSurge:0,dodges:0,dodgeCrits:0,impact:null,armor:null,defenseRerolled:0,defense:{block:0,surge:0,blank:0},mixedWarningDismissed:false};resolveScreen()}
function selectedWeaponRows(){const cards=[attacker.unit.name,...(attacker.unit.upgrades||[]).map(u=>u.name)];return cards.flatMap(card=>(profileFor(card)?.weapons||[]).map((weapon,index)=>({card,weapon,index,key:`${norm(card)}:${index}`}))).filter(x=>attackState.selected[x.key])}
function weaponHasKeyword(row,id){const profile=profileFor(row.card),ids=definitionsFor(row.card).filter(x=>x.def.category==='arme').map(x=>x.def.id);return engine.weaponKeywordActive(profile,row.weapon,ids,id)}
function pool(){const rows=selectedWeaponRows(),downgraded=new Set(attackState.moved?rows.filter(row=>weaponHasKeyword(row,'encombrant')).map(row=>row.key):[]),counts={...attackState.counts};rows.filter(row=>weaponHasKeyword(row,'souffle')).forEach(row=>{counts[row.key]=(counts[row.key]??1)*Math.max(1,attackState.visibleTargetModels||1)});const result=engine.buildPool(rows,counts,downgraded),vaapad=allResolved(attacker).some(x=>x.def.id==='maitrise-du-vaapad')?Math.min(3,Math.max(0,attackState.attackerWounds||0)):0;return {...result,blanc:result.blanc+vaapad}}
function dieBadge(color,count){return count?`<span class="dice-badge dice-badge-${color}" title="${count} dé(s) ${color}"><span>${count}</span></span>`:''}
function weaponDiceView(dice,count=1){return dice==='variable'?'<span class="variable-dice">Réserve variable</span>':`<span class="dice-row">${dice.map(d=>dieBadge(d.color,d.count*count)).join('')}</span>`}
function poolView(){const p=pool();return `<div class="dice-pool"><span>DÉS À LANCER</span><div class="dice-row dice-row-big">${dieBadge('rouge',p.rouge)}${dieBadge('noir',p.noir)}${dieBadge('blanc',p.blanc)}${p.variable?'<strong>+ réserve variable : voir la carte</strong>':''}</div></div>`}
function liveResultStrip(label,results){return `<div class="result-strip live-result-strip" aria-live="polite"><b>${label}</b><b>${diceIcon('hit','large')} <span data-live-hit>${results.hit}</span></b><b>${diceIcon('crit','large')} <span data-live-crit>${results.crit}</span></b></div>`}
function diceJourney(){const p=pool(),steps=[`<article class="journey-stage active"><small>RÉSERVE</small><strong>${dieBadge('rouge',p.rouge)}${dieBadge('noir',p.noir)}${dieBadge('blanc',p.blanc)}</strong><em>${selectedWeaponRows().length} arme(s)</em></article>`];if(attackStep>=1){const raw=attackState.roll,converted=attackResults(),conversionNotes=[];if(converted.printedToHit)conversionNotes.push(`+${converted.printedToHit} touche(s) par adrénaline`);if(converted.printedToCrit||converted.criticalUsed)conversionNotes.push(`+${converted.printedToCrit+converted.criticalUsed} critique(s) par adrénaline/Critique`);if(converted.ramUsed)conversionNotes.push(`${converted.ramUsed} résultat(s) → critique par Bélier`);steps.push(`<article class="journey-stage ${attackStep===1?'active':''}"><small>JET ET CONVERSION</small><strong>${diceIcon('hit')} ${converted.hit} ${diceIcon('crit')} ${converted.crit}</strong><em>${conversionNotes.join(' · ')||`${raw.surge||0} adrénaline(s), aucune conversion active`}</em></article>`)}if(attackStep>=2){const before=attackResults(),after=afterCover(),lostHit=before.hit-after.hit,lostCrit=before.crit-after.crit;steps.push(`<article class="journey-stage ${attackStep===2?'active':''}"><small>COUVERT ET ESQUIVES</small><strong>${diceIcon('hit')} ${after.hit} ${diceIcon('crit')} ${after.crit}</strong><em>−${lostHit} touche(s) · −${lostCrit} critique(s)</em></article>`)}if(attackStep>=3){const before=afterCover(),after=modifiedResults();steps.push(`<article class="journey-stage ${attackStep===3?'active':''}"><small>IMPACT ET ARMURE</small><strong>${diceIcon('hit')} ${after.hit} ${diceIcon('crit')} ${after.crit}</strong><em>Impact ${after.impactUsed||0} · Armure annule ${after.armorCancelled||0}</em></article>`)}if(attackStep>=4){const defense=defenseResult().result;steps.push(`<article class="journey-stage active"><small>DÉFENSE</small><strong>${diceIcon('block')} ${defense.blocks} · ${defense.wounds} blessure(s)</strong><em>Perforant annule ${defense.pierceUsed} blocage(s)</em></article>`)}return `<section class="dice-journey" aria-label="Évolution de la réserve de dés"><header><b>SUIVI DES DÉS</b><span>Chaque modification reste visible pendant toute la résolution</span></header><div>${steps.join('<span class="journey-arrow">›</span>')}</div></section>`}
function defenseResult(){const a=modifiedResults(),d=attackState.defense,p=combatProfiles[norm(defender.unit.name)],lethal=engine.applyLethal(attackKeywordValue('perforant-x'),attackKeywordValue('letal-x'),attackState.lethalAims),guardian=guardianContext(),pierceX=guardian.result.pierceRemaining,pierceImmune=allResolved(defender).some(x=>x.def.id==='immunite-perforant'||(x.def.id==='immunite-perforant-corps-a-corps'&&attackType()==='melee')),dodgesUsed=afterCover().dodgesUsed,blockActive=keywordValue(defender,'blocage')>0&&dodgesUsed>0,holdFast=attackState.engaged&&allResolved(defender).some(x=>x.def.id==='tenir-bon'),missionDefense=attackState.priorityMissionDefense&&allResolved(defender).some(x=>x.def.id==='accomplir-la-mission'),defenseSurge=holdFast||missionDefense?'block':engine.effectiveDefenseSurge(p?.defenseSurge,blockActive,dodgesUsed);return {a,d,p,lethal,guardian,pierceX,pierceImmune,dodgesUsed,blockActive,holdFast,missionDefense,defenseSurge,result:engine.applyDefense(a,d,{defenseSurge,pierceX,pierceImmune})}}
