function legalityPanel(){if(attackStep!==0)return'';const rows=selectedWeaponRows(),fixed=rows.some(row=>weaponHasKeyword(row,'fixe')),area=rows.some(row=>weaponHasKeyword(row,'arme-a-effet-de-zone')),vaapad=allResolved(attacker).some(x=>x.def.id==='maitrise-du-vaapad'),small=allResolved(defender).some(x=>x.def.id==='petit');if(!fixed&&!area&&!vaapad&&!small)return'';return `<div class="automation-card rule-highlight"><strong>CONTRÔLES DE LÉGALITÉ</strong>${vaapad?`${numberField('attackerWounds','Pions Blessure de l’attaquant (Vaapad)',attackState.attackerWounds,99)}<small>La réserve reçoit automatiquement jusqu’à 3 dés blancs supplémentaires.</small>`:''}${fixed?`<label class="situation-check"><input id="fixedArcConfirmed" type="checkbox" ${attackState.fixedArcConfirmed?'checked':''}> Une figurine du défenseur est dans l’arc de tir indiqué <small>Obligatoire pour utiliser cette arme Fixe.</small></label>`:''}${area?'<strong>ARME À EFFET DE ZONE : cette arme doit rester seule dans la réserve et chaque unité éligible reçoit une attaque distincte.</strong>':''}${small?`<label class="situation-check"><input id="smallOnlyVisible" type="checkbox" ${attackState.smallOnlyVisible?'checked':''}> La seule figurine visible est l’Alter Ego Petit <small>Dans ce cas, cette unité ne peut pas être ciblée.</small></label>`:''}</div>`}
const rulesPanelLegalityBase=rulesPanel;
rulesPanel=function(){return `${legalityPanel()}${rulesPanelLegalityBase()}`}
const stepIssueLegalityBase=stepIssue;
stepIssue=function(){const base=stepIssueLegalityBase();if(base)return base;if(attackStep===0){const rows=selectedWeaponRows();if(rows.some(row=>weaponHasKeyword(row,'arme-a-effet-de-zone'))&&rows.length!==1)return 'Une arme à effet de zone doit être la seule arme de la réserve.';if(rows.some(row=>weaponHasKeyword(row,'fixe'))&&!attackState.fixedArcConfirmed)return 'Confirmez que le défenseur se trouve dans l’arc de tir de l’arme Fixe.';if(allResolved(defender).some(x=>x.def.id==='petit')&&attackState.smallOnlyVisible)return 'Cible interdite : la seule figurine visible est l’Alter Ego doté de Petit.';}return''}
const bindLegalityBase=bindAttackInputs;
bindAttackInputs=function(){bindLegalityBase();['fixedArcConfirmed','smallOnlyVisible'].forEach(id=>{const input=$('#'+id);if(input)input.onchange=()=>{attackState[id]=input.checked;resolveScreen()}});const wounds=$('#attackerWounds');if(wounds){wounds.oninput=()=>{attackState.attackerWounds=Math.max(0,+wounds.value||0)};wounds.onchange=resolveScreen}}
$('#restart').onclick=()=>{attacker=null;defender=null;selectedArmy='p1';stage=1;pick('attacker')};pick('attacker');
